  'yamaha-dm3' => [
    'name' => 'Yamaha DM3',
    'h1' => 'Yamaha DM3 mieten in Krefeld – Jetzt verfügbar bei SLT Rental',
    'h2s' => ['Technische Daten & Leistung', 'Reichweite & Einsatzfläche', 'Aufbau & Inbetriebnahme', 'Kombination mit Licht & Effekten'],
    'useCaseBau' => 'Sicherheitsansprachen auf Großbaustellen, Durchsagen',
    'useCaseEvent' => 'Hochzeiten, Konzerte, Firmenfeiern, Stadtfeste, DJ-Sets, Konferenzen',
    'useCasePrivat' => 'Gartenparty, Geburtstagsfeier, Vereinsfest, Schulabschlussfeier',
    'faqs' => [
      ['q' => 'Für wie viele Personen / welche Fläche reicht diese Anlage?', 'a' => 'Die Leistung entnehmen Sie den technischen Daten. Als Richtwert: 1 W RMS Ausgangsleistung reicht für ca. 1–2 Personen in Innenräumen. Für Außenveranstaltungen mindestens die doppelte Leistung einplanen. Wir beraten Sie gerne zur optimalen Anlagenauswahl.'],
      ['q' => 'Wie wird die Anlage in Betrieb genommen?', 'a' => 'Die Anlage ist steckerfertig – Lautsprecher anschließen, Quellgerät verbinden und einschalten. Eine kurze Einweisung erhalten Sie bei Abholung. Für professionelle Events empfehlen wir einen Techniker zu buchen.'],
      ['q' => 'Kann die Anlage auch im Außenbereich betrieben werden?', 'a' => 'Das hängt vom Modell ab. Aktive Beschallungssysteme können grundsätzlich im Außenbereich eingesetzt werden, sollten aber vor direktem Regen und extremen Temperaturen geschützt werden. Bitte bei Fragen zur Wetterfestigkeit nachfragen.'],
      ['q' => 'Ist ein Mischpult oder Verstärker separat notwendig?', 'a' => 'Bei aktiven Systemen (mit eingebautem Verstärker) ist kein separater Verstärker nötig. Ein Mischpult ist optional – empfehlenswert bei mehreren Quellen (Mikrofon, Laptop, DJ). Passende Mischpulte sind bei uns separat erhältlich.'],
    ],
  ],
  'zeltboden-anthrazit' => [
    'name' => 'Zeltboden Anthrazit 0,86m²',
    'h1' => 'Eventboden / Zeltboden Anthrazit mieten – robust, belastbar & schnell verlegt',
    'h2s' => ['Technische Daten & Material', 'Verlegung & Handhabung', 'Einsatzbereiche', 'Kombination mit Zelten & Equipment'],
    'useCaseBau' => 'Baustellenzufahrt, temporäre Lagerflächen, Personenwege auf unbefestigtem Untergrund',
    'useCaseEvent' => 'Zeltböden für Hochzeiten, Firmenfeiern, Stadtfeste, Messen, Konzerte',
    'useCasePrivat' => 'Gartenfest, Jubiläum, Gartenparty auf Rasen, Kommunion, Silvesterparty',
    'faqs' => [
      ['q' => 'Aus welchem Material besteht der Eventboden?', 'a' => 'Der Eventboden besteht aus recyceltem Kunststoff-Mix. Jede Matte ist 1.000 × 860 mm groß, 23 mm stark und wiegt 15 kg. Die Nutzfläche pro Stück beträgt 0,80 m².'],
      ['q' => 'Wie belastbar ist der Zeltboden?', 'a' => 'Der Boden ist mit ca. 15 t/m² auf festem Untergrund extrem belastbar – geeignet für Fahrzeuge, schweres Equipment und hohe Personenfrequenz.'],
